import { claim, policyFor, type ClaimResult, type Incident, type Policy } from "./claimSettlement.js";
import { quote, type Customer, type QuoteItem, type QuoteResult } from "./premium.js";

export type { ClaimResult, Damage, Incident } from "./claimSettlement.js";
export type { Customer, QuoteItem, QuoteResult } from "./premium.js";

export interface QuoteStep {
  op: "quote";
  items: QuoteItem[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export type StepResult = QuoteResult | ClaimResult;

function isFollowUpContract(stepIndex: number): boolean {
  return stepIndex > 0;
}

export function runScenario(scenario: Scenario): { results: StepResult[] } {
  const policies = new Map<number, Policy>();
  const results = scenario.steps.map((step, stepIndex): StepResult => {
    if (step.op === "claim") {
      return claim(step.incident, policies.get(step.policy) as Policy);
    }
    policies.set(stepIndex, policyFor(step.items));
    return quote(step.items, scenario.customer, isFollowUpContract(stepIndex));
  });
  return { results };
}
export interface QuoteItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Customer {
  yearsWithMHPCO: number;
}

export interface QuoteResult {
  premium: number;
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const PERCENT = 100;
const CURSE_SURCHARGE_PERCENT = 50;
const LOYALTY_DISCOUNT_PERCENT = 20;
const LOYALTY_YEARS = 2;
const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
const HIGH_ENCHANTMENT_THRESHOLD = 5;
const BASE_PREMIUM_PER_COMPONENT = 25;
const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

function isComponent(item: QuoteItem): boolean {
  return COMPONENT_TYPES.has(item.type);
}

function isMainItem(item: QuoteItem): boolean {
  return item.type in MAIN_ITEM_BASE_PREMIUMS;
}

function mainItemsOf(items: QuoteItem[]): QuoteItem[] {
  return items.filter(isMainItem);
}

function mainItemBasePremiumOf(mainItem: QuoteItem): number {
  return MAIN_ITEM_BASE_PREMIUMS[mainItem.type];
}

function mainItemsBasePremiumOf(items: QuoteItem[]): number {
  return mainItemsOf(items).reduce((sum, mainItem) => sum + mainItemBasePremiumOf(mainItem), 0);
}

function alikenessOf(component: QuoteItem): string {
  return component.type;
}

function alikeComponentCountsOf(items: QuoteItem[]): number[] {
  const countsByAlikeness = new Map<string, number>();
  for (const alikeness of items.filter(isComponent).map(alikenessOf)) {
    countsByAlikeness.set(alikeness, (countsByAlikeness.get(alikeness) ?? 0) + 1);
  }
  return [...countsByAlikeness.values()];
}

function isBuildingBlock(alikeComponentCount: number): boolean {
  return alikeComponentCount === BLOCK_SIZE;
}

function alikeComponentsBasePremiumOf(count: number): number {
  return isBuildingBlock(count) ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUM_PER_COMPONENT;
}

function componentsBasePremiumOf(items: QuoteItem[]): number {
  return alikeComponentCountsOf(items).reduce((sum, count) => sum + alikeComponentsBasePremiumOf(count), 0);
}

function policyBasePremiumOf(items: QuoteItem[]): number {
  return mainItemsBasePremiumOf(items) + componentsBasePremiumOf(items);
}

function percentOf(amount: number, percent: number): number {
  return (amount * percent) / PERCENT;
}

function firstInsuranceSurchargeOn(policyBasePremium: number): number {
  return percentOf(policyBasePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
}

function premiumRoundedInMHPCOsFavor(premium: number): number {
  return Math.ceil(premium);
}

function isHighlyEnchanted(mainItem: QuoteItem): boolean {
  return (mainItem.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
}

function curseSurchargePercentOf(mainItem: QuoteItem): number {
  return mainItem.cursed ? CURSE_SURCHARGE_PERCENT : 0;
}

function highEnchantmentSurchargePercentOf(mainItem: QuoteItem): number {
  return isHighlyEnchanted(mainItem) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0;
}

function riskSurchargePercentOf(mainItem: QuoteItem): number {
  return curseSurchargePercentOf(mainItem) + highEnchantmentSurchargePercentOf(mainItem);
}

function riskSurchargeOn(mainItem: QuoteItem): number {
  return percentOf(mainItemBasePremiumOf(mainItem), riskSurchargePercentOf(mainItem));
}

function riskSurchargesOf(items: QuoteItem[]): number {
  return mainItemsOf(items).reduce((sum, mainItem) => sum + riskSurchargeOn(mainItem), 0);
}

function isLoyalCustomer(customer: Customer): boolean {
  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
}

function loyaltyDiscountOn(policyBasePremium: number, customer: Customer): number {
  return isLoyalCustomer(customer) ? percentOf(policyBasePremium, LOYALTY_DISCOUNT_PERCENT) : 0;
}

function followUpContractDiscountOn(policyBasePremium: number, isFollowUpContract: boolean): number {
  return isFollowUpContract ? percentOf(policyBasePremium, FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT) : 0;
}

function policyWideModifiersOn(policyBasePremium: number, customer: Customer, isFollowUpContract: boolean): number {
  return (
    firstInsuranceSurchargeOn(policyBasePremium) -
    loyaltyDiscountOn(policyBasePremium, customer) -
    followUpContractDiscountOn(policyBasePremium, isFollowUpContract)
  );
}

function assertInsurable(item: QuoteItem): void {
  if (!isMainItem(item) && !isComponent(item)) {
    throw new Error(`Unknown item type: ${item.type}`);
  }
}

export function quote(items: QuoteItem[], customer: Customer, isFollowUpContract: boolean): QuoteResult {
  items.forEach(assertInsurable);
  const policyBasePremium = policyBasePremiumOf(items);
  const unroundedPremium =
    policyBasePremium +
    riskSurchargesOf(items) +
    policyWideModifiersOn(policyBasePremium, customer, isFollowUpContract) +
    PROCESSING_FEE;
  return { premium: premiumRoundedInMHPCOsFavor(unroundedPremium) };
}
import type { QuoteItem } from "./premium.js";

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export interface Policy {
  remainingCap: number;
}

const DEDUCTIBLE_PER_DAMAGE = 100;
const CAP_MULTIPLIER = 2;

const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
  amulet: 600,
};

function insuranceSumOf(items: QuoteItem[]): number {
  return items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
}

export function policyFor(items: QuoteItem[]): Policy {
  return { remainingCap: insuranceSumOf(items) * CAP_MULTIPLIER };
}

function reimbursementAfterDeductibleOf(damage: Damage): number {
  return damage.amount - DEDUCTIBLE_PER_DAMAGE;
}

export function claim(incident: Incident, policy: Policy): ClaimResult {
  const desiredPayout = incident.damages.reduce((sum, damage) => sum + reimbursementAfterDeductibleOf(damage), 0);
  const payout = Math.min(desiredPayout, policy.remainingCap);
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
}
import { describe, expect, it } from "vitest";
import { runScenario, type QuoteItem, type Step } from "./claimOffice.js";

const quote = (items: QuoteItem[]) => ({ op: "quote" as const, items });

const scenarioResultsFor = (yearsWithMHPCO: number, ...steps: Step[]) =>
  runScenario({ customer: { yearsWithMHPCO }, steps }).results;

const premiumFor = (yearsWithMHPCO: number, items: QuoteItem[]) => scenarioResultsFor(yearsWithMHPCO, quote(items))[0];

const alikeComponents = (type: string, count: number): QuoteItem[] => Array.from({ length: count }, () => ({ type }));
const runes = (count: number) => alikeComponents("rune", count);
const moonstones = (count: number) => alikeComponents("moonstone", count);

describe("quote", () => {
  it("empty item list (newcomer) -> premium 5 G (only the processing fee)", () => {
    expect(premiumFor(0, [])).toEqual({ premium: 5 });
  });
  it("newcomer, plain steel sword enchantment 3 -> 100 base + 10 first insurance + 5 fee = 115 G", () => {
    expect(premiumFor(0, [{ type: "sword", material: "steel", enchantment: 3 }])).toEqual({ premium: 115 });
  });
  it("newcomer, plain amulet -> 60 + 6 + 5 = 71 G", () => {
    expect(premiumFor(0, [{ type: "amulet" }])).toEqual({ premium: 71 });
  });
  it("newcomer, plain staff -> 80 + 8 + 5 = 93 G", () => {
    expect(premiumFor(0, [{ type: "staff" }])).toEqual({ premium: 93 });
  });
  it("newcomer, plain potion -> 40 + 4 + 5 = 49 G", () => {
    expect(premiumFor(0, [{ type: "potion" }])).toEqual({ premium: 49 });
  });
  it("newcomer, 2 runes -> base 50 G -> 50 + 5 + 5 = 60 G", () => {
    expect(premiumFor(0, runes(2))).toEqual({ premium: 60 });
  });
  it("newcomer, 1 rune -> 25 + 2.5 + 5 = 32.5 -> rounded up in MHPCO's favor to 33 G", () => {
    expect(premiumFor(0, [{ type: "rune" }])).toEqual({ premium: 33 });
  });
  it("newcomer, 1 moonstone -> 25 + 2.5 + 5 = 32.5 -> 33 G", () => {
    expect(premiumFor(0, [{ type: "moonstone" }])).toEqual({ premium: 33 });
  });
  it("newcomer, 3 runes -> block base 60 G -> 60 + 6 + 5 = 71 G", () => {
    expect(premiumFor(0, runes(3))).toEqual({ premium: 71 });
  });
  it("newcomer, 4 runes -> no block (exactly 3 required), base 100 G -> 115 G", () => {
    expect(premiumFor(0, runes(4))).toEqual({ premium: 115 });
  });
  it("newcomer, 7 runes -> no block, base 175 G -> 197.5 -> rounded up to 198 G", () => {
    expect(premiumFor(0, runes(7))).toEqual({ premium: 198 });
  });
  it("newcomer, 2 runes + 1 moonstone -> no block (different types), base 75 G -> 87.5 -> 88 G", () => {
    expect(premiumFor(0, [...runes(2), ...moonstones(1)])).toEqual({ premium: 88 });
  });
  it("newcomer, 3 runes + 3 moonstones -> two blocks, base 120 G -> 137 G", () => {
    expect(premiumFor(0, [...runes(3), ...moonstones(3)])).toEqual({ premium: 137 });
  });
  it("newcomer, cursed steel sword enchantment 3 -> 100 + 50 curse + 10 first = 160 + 5 = 165 G", () => {
    expect(premiumFor(0, [{ type: "sword", material: "steel", enchantment: 3, cursed: true }])).toEqual({ premium: 165 });
  });
  it("newcomer, cursed sword + plain amulet -> curse only on sword: 160 + 50 + 16 + 5 = 231 G", () => {
    expect(premiumFor(0, [{ type: "sword", cursed: true }, { type: "amulet" }])).toEqual({ premium: 231 });
  });
  it("newcomer, sword enchantment exactly 5 -> high-enchantment surcharge: 100 + 30 + 10 + 5 = 145 G", () => {
    expect(premiumFor(0, [{ type: "sword", enchantment: 5 }])).toEqual({ premium: 145 });
  });
  it("newcomer, sword enchantment 4 -> no high-enchantment surcharge: 115 G", () => {
    expect(premiumFor(0, [{ type: "sword", enchantment: 4 }])).toEqual({ premium: 115 });
  });
  it("newcomer, cursed sword enchantment 5 -> both surcharges: 100 + 50 + 30 + 10 + 5 = 195 G", () => {
    expect(premiumFor(0, [{ type: "sword", enchantment: 5, cursed: true }])).toEqual({ premium: 195 });
  });
  it("newcomer, cursed sword enchantment 4 -> only curse surcharge: 165 G", () => {
    expect(premiumFor(0, [{ type: "sword", enchantment: 4, cursed: true }])).toEqual({ premium: 165 });
  });
  it("newcomer, sword enchantment 5 + plain amulet -> surcharge only on sword: 160 + 30 + 16 + 5 = 211 G", () => {
    expect(premiumFor(0, [{ type: "sword", enchantment: 5 }, { type: "amulet" }])).toEqual({ premium: 211 });
  });
  it("customer with exactly 2 years, plain sword -> loyalty discount: 100 - 20 + 10 + 5 = 95 G", () => {
    expect(premiumFor(2, [{ type: "sword" }])).toEqual({ premium: 95 });
  });
  it("customer with 1 year, plain sword -> no loyalty discount: 115 G", () => {
    expect(premiumFor(1, [{ type: "sword" }])).toEqual({ premium: 115 });
  });
  it("newcomer, second quote in scenario, plain sword -> follow-up discount: 100 + 10 - 15 + 5 = 100 G", () => {
    const sword = { type: "sword" };
    const results = scenarioResultsFor(0, quote([sword]), quote([sword]));
    expect(results[1]).toEqual({ premium: 100 });
  });
  it("newcomer, third quote in scenario, plain sword -> follow-up discount still 15 %: 100 G", () => {
    const sword = { type: "sword" };
    const results = scenarioResultsFor(0, quote([sword]), quote([sword]), quote([sword]));
    expect(results[2]).toEqual({ premium: 100 });
  });
  it("3 years, second quote, cursed sword enchantment 7 -> 100 + 50 + 30 - 20 + 10 - 15 + 5 = 160 G", () => {
    const cursedSword = { type: "sword", material: "steel", enchantment: 7, cursed: true };
    const results = scenarioResultsFor(3, quote([{ type: "amulet" }]), quote([cursedSword]));
    expect(results[1]).toEqual({ premium: 160 });
  });
  it("quote with unknown item type 'broomstick' -> runScenario throws an Error (chosen contract: domain throws, CLI maps to non-zero exit)", () => {
    expect(() => premiumFor(0, [{ type: "broomstick" }])).toThrow(Error);
  });
});

const claimOf = (...damages: { itemType: string; amount: number }[]) => ({
  op: "claim" as const,
  policy: 0,
  incident: { cause: "dragon attack", damages },
});

const claimResultsFor = (items: QuoteItem[], ...claims: ReturnType<typeof claimOf>[]) =>
  scenarioResultsFor(0, quote(items), ...claims).slice(1);

describe("claim", () => {
  it("schema example: 5 years, silver amulet enchantment 2, fire damage 200 -> premium 59 G, payout 100 G, remainingCap 1100 G", () => {
    const { results } = runScenario({
      customer: { yearsWithMHPCO: 5 },
      steps: [
        quote([{ type: "amulet", material: "silver", enchantment: 2, cursed: false }]),
        { op: "claim", policy: 0, incident: { cause: "fire", damages: [{ itemType: "amulet", amount: 200 }] } },
      ],
    });
    expect(results).toEqual([{ premium: 59 }, { payout: 100, remainingCap: 1100 }]);
  });
  it("regular steel sword enchantment 3, damage 500 -> payout 400 G, remainingCap 1600 G", () => {
    const sword = { type: "sword", material: "steel", enchantment: 3 };
    expect(claimResultsFor([sword], claimOf({ itemType: "sword", amount: 500 }))).toEqual([{ payout: 400, remainingCap: 1600 }]);
  });
  it.todo("rune, damage 200 -> payout 100 G, remainingCap 400 G");
  it.todo("steel sword enchantment 9, damage 1000 -> 50 % then deductible: payout 400 G");
  it.todo("dragon-material sword enchantment 9, damage 1000 -> 50 % rule wins: payout 400 G");
  it.todo("dragon-material sword enchantment 5, damage 800 -> full reimbursement: payout 700 G");
  it.todo("dragon-material sword enchantment exactly 8, damage 1000 -> high-enchantment clause applies: payout 400 G");
  it.todo("steel sword enchantment 9, damage 901 -> 350.5 -> rounded down in MHPCO's favor to 350 G");
  it.todo("sword + amulet, dragon attack damages sword 500 and amulet 300 -> deductible per item: payout 600 G, remainingCap 2600 G");
  it.todo("two swords insured, both damaged 500 each -> separate deductibles: payout 800 G, remainingCap 3200 G (cap 4000)");
  it.todo("cursed sword, damage 1500 -> cap based on unmodified value 2000: payout 1400 G, remainingCap 600 G");
  it.todo("sword + 3 runes (block), sword damage 500 -> insurance sum 1750, cap 3500: payout 400 G, remainingCap 3100 G");
  it.todo("sword, two successive claims of 1500 -> payouts 1400 G then 600 G, remainingCap 600 G then 0 G");
  it.todo("claim for an amulet when only a sword is insured -> runScenario throws an Error");
  it.todo("claim for an unknown item type -> runScenario throws an Error");
  it.todo("two sword damages but only one sword insured -> whole claim rejected: runScenario throws an Error");
  it.todo("damage amount -200 -> runScenario throws an Error");
});
